module.exports = function(RED) {
    const nodeReds = [];
    const WebSocket = require('ws');

    const wss = new WebSocket.Server({ port: 8766 });

    wss.on('connection', function connection(ws) {
        nodeReds.forEach(nodeRed => {
            nodeRed.status({fill:"green",shape:"dot",text:"connected"});
        });

        ws.on('message', function incoming(message) {
            const bufferString = message.toString('utf8');
            const jsonData = JSON.parse(bufferString);

            nodeReds.forEach(nodeRed => {
                nodeRed.send({payload: jsonData});
            });
        });

        ws.on('close', function close() {          
            nodeReds.forEach(nodeRed => {
                nodeRed.status({fill:"red",shape:"ring",text:"disconnected"});
            });
        });
    });

    function WebSocketServerNode(config) {
        RED.nodes.createNode(this, config);

        var node = this;
        nodeRed = this;
        nodeReds.push(node);
        // node.status({fill:"red",shape:"ring",text:"disconnected"});

        this.on('input', function(msg, send, done) {});
    }

    RED.nodes.registerType('IOT Get', WebSocketServerNode);
};